	DR.OpenBox(c, 'offer')
	eq(typed(), 2, 'two offers wait in the chat box')
	DR.OpenBox(c, 'offer')
	eq(typed(), 2, 'a third unsent offer is not put in chat again')
	T.clean(w)
end)

